#pragma once

#include <vector>
#include <string_view>
#include <span>
#include <atomic>
#include <optional>
#include <cstddef>

namespace ws {

class Buffer {
public:
    enum class NewLine { LF, CRLF };

    Buffer(std::size_t size = 1000) noexcept : buf_(size), read_pos_(0), write_pos_(0) {}
    Buffer(std::span<const std::byte> bytes) noexcept : buf_(bytes.begin(), bytes.end()), read_pos_(0), write_pos_(bytes.size()) {}
    Buffer(std::initializer_list<std::byte> bytes) noexcept : buf_(bytes), read_pos_(0), write_pos_(bytes.size()) {}
    Buffer(std::string_view str) noexcept : buf_(str.begin(), str.end()), read_pos_(0), write_pos_(str.size()) {}
    Buffer(const Buffer&) noexcept = default;
    Buffer(Buffer&&) noexcept = default;

    Buffer& operator=(const Buffer&) noexcept = default;
    Buffer& operator=(Buffer&&) noexcept = default;

    std::size_t WritableSize() const noexcept { return buf_.size() - write_pos_; }
    std::size_t ReadableSize() const noexcept { return write_pos_ - read_pos_; }
    std::byte Peek() const noexcept { return buf_[read_pos_]; }
    std::span<const std::byte> ReadableBytes() const noexcept { return std::span<const std::byte>(buf_.data() + read_pos_, ReadableSize()); }
    std::string_view ReadableString() const noexcept { return std::string_view(reinterpret_cast<const char*>(buf_.data()) + read_pos_, ReadableSize()); }
    std::span<std::byte> WritableBytes() const noexcept { return std::span<std::byte>(buf_.data() + write_pos_, WritableSize()); }

    void Append(std::span<const std::byte> bytes) noexcept {
        EnsureWriteableSize(bytes.size());
        std::copy(bytes.begin(), bytes.end(), WriteIter());
        HasWritten(bytes.size());
    }

    void Append(std::initializer_list<std::byte> bytes) noexcept {
        EnsureWriteableSize(bytes.size());
        std::copy(bytes.begin(), bytes.end(), WriteIter());
        HasWritten(bytes.size());
    }

    void Append(std::string_view str, std::optional<NewLine> new_line = std::nullopt) noexcept {
        EnsureWriteableSize(str.size() + (new_line ? 2 : 0));
        auto iter = WriteIter();
        std::copy(str.begin(), str.end(), iter);
        iter += str.size();
        if (new_line == NewLine::LF) {
            *iter++ = static_cast<std::byte>('\n');
        } else if (new_line == NewLine::CRLF) {
            *iter++ = static_cast<std::byte>('\r');
            *iter++ = static_cast<std::byte>('\n');
        }
        HasWritten(str.size() + (new_line ? 2 : 0));
    }

    void Append(const void* data, std::size_t size) noexcept {
        EnsureWriteableSize(size);
        std::copy(static_cast<const std::byte*>(data), static_cast<const std::byte*>(data) + size, WriteIter());
        HasWritten(size);
    }

    void Append(const Buffer& buf) noexcept {
        Append(buf.ReadableBytes());
    }

    void EnsureWriteableSize(std::size_t size) noexcept {
        if (WritableSize() < size) {
            MakeSpace(size);
        }
    }

    void HasWritten(std::size_t size) noexcept { write_pos_ += size; }
    void Retrieve(std::size_t size) noexcept { read_pos_ += size; }
    void RetrieveUntil(const void* addr) noexcept { read_pos_ = static_cast<const std::byte*>(addr) - buf_.data(); }
    std::size_t RetrieveAll() noexcept {
        auto n = ReadableSize();
        read_pos_ = write_pos_;
        return n;
    }

    std::string_view RetrieveAllToString() noexcept {
        auto str = ReadableString();
        RetrieveAll();
        return str;
    }

    void Clear() noexcept { read_pos_ = 0; write_pos_ = 0; }
    bool Empty() const noexcept { return ReadableSize() == 0; }

protected:
    std::size_t PrependableSize() const noexcept { return read_pos_; }
    void MakeSpace(std::size_t size) noexcept {
        if (PrependableSize() + WritableSize() < size) {
            buf_.resize(write_pos_ + size);
        } else {
            std::copy(ReadIter(), WriteIter(), buf_.begin());
            write_pos_ -= read_pos_;
            read_pos_ = 0;
        }
    }

    std::byte* ReadIter() const noexcept { return buf_.data() + read_pos_; }
    std::byte* WriteIter() const noexcept { return buf_.data() + write_pos_; }

private:
    std::vector<std::byte> buf_;
    std::atomic<std::size_t> read_pos_;
    std::atomic<std::size_t> write_pos_;
};

Buffer& operator<<(Buffer& buf, std::string_view str) noexcept {
    buf.Append(str);
    return buf;
}

Buffer& operator<<(Buffer& to, const Buffer& from) noexcept {
    to.Append(from);
    return to;
}

Buffer& operator<<(Buffer& buf, std::span<const std::byte> bytes) noexcept {
    buf.Append(bytes);
    return buf;
}

Buffer& operator<<(Buffer& buf, std::initializer_list<std::byte> bytes) noexcept {
    buf.Append(bytes);
    return buf;
}

}

#pragma once

#include "Buffer.h"
#include <ws/io/IReadWriter.h>

namespace ws {

class IOBuffer : public Buffer {
public:
    using Buffer::Buffer;

    void ReadFrom(io::IReadWriter& io) {
        std::byte buffer[1024];
        while (true) {
            auto n = io.Read(buffer, sizeof(buffer));
            if (n == 0) break;
            Append(std::span<const std::byte>(buffer, n));
        }
    }

    void WriteTo(io::IReadWriter& io) {
        while (!Empty()) {
            auto bytes = ReadableBytes();
            auto n = io.Write(bytes.data(), bytes.size());
            Retrieve(n);
        }
    }
};

}
